CREATE TABLE public.crm_users(user_id uuid PRIMARY KEY, email text NOT NULL, role text NOT NULL DEFAULT 'sales' CHECK(role IN ('admin','sales')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.crm_users TO authenticated; GRANT ALL ON public.crm_users TO service_role;
ALTER TABLE public.crm_users ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.crm_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT CASE WHEN active THEN role ELSE 'disabled' END FROM public.crm_users WHERE user_id=auth.uid()), CASE WHEN public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.cms_members WHERE user_id=auth.uid() AND role='owner') THEN 'admin' END) $$;
GRANT EXECUTE ON FUNCTION public.crm_role() TO authenticated; REVOKE EXECUTE ON FUNCTION public.crm_role() FROM PUBLIC,anon;
CREATE POLICY crm_users_read ON public.crm_users FOR SELECT TO authenticated USING(public.crm_role()='admin' OR user_id=auth.uid());
CREATE TABLE public.crm_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), sla_hours integer NOT NULL DEFAULT 24 CHECK(sla_hours BETWEEN 1 AND 720), stages jsonb NOT NULL DEFAULT '["opportunity","meeting held","quotation","negotiation","won","lost"]', round_robin_cursor integer NOT NULL DEFAULT 0);
GRANT SELECT,INSERT,UPDATE ON public.crm_settings TO authenticated; GRANT ALL ON public.crm_settings TO service_role;
ALTER TABLE public.crm_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_settings_read ON public.crm_settings FOR SELECT TO authenticated USING(public.crm_role() IN ('admin','sales'));
CREATE POLICY crm_settings_manage ON public.crm_settings FOR ALL TO authenticated USING(public.crm_role()='admin') WITH CHECK(public.crm_role()='admin');
CREATE TABLE public.leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text, email text, company text, source text NOT NULL DEFAULT 'direct', attribution jsonb NOT NULL DEFAULT '{}', consent boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','qualified','unqualified')), reason text NOT NULL DEFAULT '', owner uuid, created_at timestamptz NOT NULL DEFAULT now(), first_response_at timestamptz, request_id uuid UNIQUE REFERENCES public.contact_requests(id), merged_into uuid REFERENCES public.leads(id));
GRANT SELECT,INSERT,UPDATE ON public.leads TO authenticated; GRANT ALL ON public.leads TO service_role;
ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY leads_access ON public.leads FOR ALL TO authenticated USING(public.crm_role()='admin' OR (public.crm_role()='sales' AND owner=auth.uid())) WITH CHECK(public.crm_role()='admin' OR (public.crm_role()='sales' AND owner=auth.uid()));
CREATE INDEX leads_owner_idx ON public.leads(owner); CREATE INDEX leads_phone_idx ON public.leads(regexp_replace(phone,'[^0-9]','','g')); CREATE INDEX leads_email_idx ON public.leads(lower(email));
CREATE TABLE public.deals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL UNIQUE REFERENCES public.leads(id), value numeric NOT NULL DEFAULT 0 CHECK(value>=0), expected_close_date date, owner uuid, stage text NOT NULL DEFAULT 'opportunity', reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), stage_changed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.deals TO authenticated; GRANT ALL ON public.deals TO service_role;
ALTER TABLE public.deals ENABLE ROW LEVEL SECURITY;
CREATE POLICY deals_access ON public.deals FOR ALL TO authenticated USING(public.crm_role()='admin' OR (public.crm_role()='sales' AND owner=auth.uid())) WITH CHECK(public.crm_role()='admin' OR (public.crm_role()='sales' AND owner=auth.uid()));
CREATE TABLE public.activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL CHECK(type IN ('call','whatsapp','email','note','meeting','task')), lead_id uuid REFERENCES public.leads(id), deal_id uuid REFERENCES public.deals(id), owner uuid NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','done')), outcome text NOT NULL DEFAULT '', due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(lead_id,deal_id)=1));
GRANT SELECT,INSERT,UPDATE ON public.activities TO authenticated; GRANT ALL ON public.activities TO service_role;
ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY activities_access ON public.activities FOR ALL TO authenticated USING(public.crm_role()='admin' OR (public.crm_role()='sales' AND owner=auth.uid() AND (EXISTS(SELECT 1 FROM public.leads l WHERE l.id=lead_id AND l.owner=auth.uid()) OR EXISTS(SELECT 1 FROM public.deals d WHERE d.id=deal_id AND d.owner=auth.uid())))) WITH CHECK(public.crm_role()='admin' OR (public.crm_role()='sales' AND owner=auth.uid() AND (EXISTS(SELECT 1 FROM public.leads l WHERE l.id=lead_id AND l.owner=auth.uid()) OR EXISTS(SELECT 1 FROM public.deals d WHERE d.id=deal_id AND d.owner=auth.uid()))));
CREATE FUNCTION public.crm_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target_owner uuid; current_stages jsonb; BEGIN
 IF auth.uid() IS NOT NULL AND public.crm_role() NOT IN ('admin','sales') THEN RAISE EXCEPTION 'Forbidden'; END IF;
 IF TG_TABLE_NAME IN ('leads','deals') AND TG_OP='UPDATE' AND public.crm_role()='sales' AND NEW.owner IS DISTINCT FROM OLD.owner THEN RAISE EXCEPTION 'Only Admin can assign'; END IF;
 IF TG_TABLE_NAME='leads' THEN IF NEW.status='unqualified' AND trim(NEW.reason)='' THEN RAISE EXCEPTION 'Unqualified reason required'; END IF; IF TG_OP='UPDATE' AND OLD.merged_into IS NOT NULL THEN RAISE EXCEPTION 'Merged record is read only'; END IF; END IF;
 IF TG_TABLE_NAME='deals' THEN
 SELECT owner INTO target_owner FROM public.leads WHERE id=NEW.lead_id AND status='qualified' AND merged_into IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Qualified lead required'; END IF;
 IF TG_OP='INSERT' THEN NEW.owner:=target_owner; END IF;
 SELECT stages INTO current_stages FROM public.crm_settings WHERE id=1;
 current_stages:=COALESCE(current_stages,'["opportunity","meeting held","quotation","negotiation","won","lost"]');
 IF NOT current_stages ? NEW.stage THEN RAISE EXCEPTION 'Invalid stage'; END IF;
 IF NEW.stage='lost' AND trim(NEW.reason)='' THEN RAISE EXCEPTION 'Lost reason required'; END IF;
 IF TG_OP='UPDATE' AND NEW.stage IS DISTINCT FROM OLD.stage THEN NEW.stage_changed_at:=now(); END IF;
 END IF;
 IF TG_TABLE_NAME='activities' THEN
 IF NEW.lead_id IS NOT NULL THEN SELECT owner INTO target_owner FROM public.leads WHERE id=NEW.lead_id AND merged_into IS NULL; ELSE SELECT owner INTO target_owner FROM public.deals WHERE id=NEW.deal_id; END IF;
 IF public.crm_role()='sales' AND (target_owner IS DISTINCT FROM auth.uid() OR NEW.owner IS DISTINCT FROM auth.uid()) THEN RAISE EXCEPTION 'Forbidden'; END IF;
 IF NEW.type IN ('task','meeting') AND NEW.due_at IS NULL THEN RAISE EXCEPTION 'Date required'; END IF;
 END IF; RETURN NEW; END $$;
CREATE TRIGGER leads_validate BEFORE INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.crm_validate();
CREATE TRIGGER deals_validate BEFORE INSERT OR UPDATE ON public.deals FOR EACH ROW EXECUTE FUNCTION public.crm_validate();
CREATE TRIGGER activities_validate BEFORE INSERT OR UPDATE ON public.activities FOR EACH ROW EXECUTE FUNCTION public.crm_validate();
CREATE FUNCTION public.crm_response() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.type IN ('call','whatsapp','email','meeting') THEN UPDATE public.leads SET first_response_at=COALESCE(first_response_at,now()),status=CASE WHEN status='new' THEN 'contacted' ELSE status END WHERE id=COALESCE(NEW.lead_id,(SELECT lead_id FROM public.deals WHERE id=NEW.deal_id)); END IF; RETURN NEW; END $$;
CREATE TRIGGER activities_response AFTER INSERT ON public.activities FOR EACH ROW EXECUTE FUNCTION public.crm_response();
CREATE FUNCTION public.crm_capture() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.leads(name,phone,email,company,source,attribution,consent,request_id,created_at) VALUES(NEW.name,NEW.phone,NEW.email,NEW.company,COALESCE(NULLIF(NEW.utm->>'utm_source',''),'direct'),NEW.utm,NEW.consent,NEW.id,NEW.created_at); RETURN NEW; END $$;
CREATE TRIGGER contact_crm_capture AFTER INSERT ON public.contact_requests FOR EACH ROW EXECUTE FUNCTION public.crm_capture();
INSERT INTO public.leads(name,phone,email,company,source,attribution,consent,request_id,created_at) SELECT name,phone,email,company,COALESCE(NULLIF(utm->>'utm_source',''),'direct'),utm,consent,id,created_at FROM public.contact_requests;
CREATE FUNCTION public.crm_assign(ids uuid[], rep uuid DEFAULT NULL, rotating boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE reps uuid[]; item uuid; chosen uuid; cursor_value integer; BEGIN IF public.crm_role() IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Forbidden'; END IF;
 INSERT INTO public.crm_settings(id) VALUES(1) ON CONFLICT DO NOTHING; SELECT round_robin_cursor INTO cursor_value FROM public.crm_settings WHERE id=1 FOR UPDATE;
 IF rotating THEN SELECT array_agg(user_id ORDER BY created_at,user_id) INTO reps FROM public.crm_users WHERE active AND role='sales'; IF COALESCE(array_length(reps,1),0)=0 THEN RAISE EXCEPTION 'No active Sales users'; END IF; ELSIF rep IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.crm_users WHERE user_id=rep AND active) THEN RAISE EXCEPTION 'Inactive owner'; END IF;
 FOREACH item IN ARRAY ids LOOP chosen:=rep; IF rotating THEN chosen:=reps[1+(cursor_value % array_length(reps,1))]; cursor_value:=cursor_value+1; END IF;
 UPDATE public.leads SET owner=chosen WHERE id=item AND merged_into IS NULL; UPDATE public.deals SET owner=chosen WHERE lead_id=item; UPDATE public.activities SET owner=COALESCE(chosen,owner) WHERE lead_id=item OR deal_id IN (SELECT id FROM public.deals WHERE lead_id=item); END LOOP;
 UPDATE public.crm_settings SET round_robin_cursor=cursor_value WHERE id=1; END $$;
REVOKE ALL ON FUNCTION public.crm_assign(uuid[],uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_assign(uuid[],uuid,boolean) TO authenticated;
CREATE FUNCTION public.crm_merge(keep_id uuid, remove_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k public.leads; r public.leads; BEGIN IF public.crm_role() IS DISTINCT FROM 'admin' OR keep_id=remove_id THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO k FROM public.leads WHERE id=keep_id AND merged_into IS NULL FOR UPDATE; SELECT * INTO r FROM public.leads WHERE id=remove_id AND merged_into IS NULL FOR UPDATE; IF k.id IS NULL OR r.id IS NULL THEN RAISE EXCEPTION 'Record not found'; END IF;
 IF EXISTS(SELECT 1 FROM public.deals WHERE lead_id=keep_id) AND EXISTS(SELECT 1 FROM public.deals WHERE lead_id=remove_id) THEN RAISE EXCEPTION 'Both records have opportunities; resolve them before merging'; END IF;
 UPDATE public.leads SET phone=COALESCE(NULLIF(k.phone,''),r.phone),email=COALESCE(NULLIF(k.email,''),r.email),company=COALESCE(NULLIF(k.company,''),r.company),consent=k.consent OR r.consent,first_response_at=COALESCE(k.first_response_at,r.first_response_at),status=CASE WHEN EXISTS(SELECT 1 FROM public.deals WHERE lead_id=remove_id) THEN 'qualified' ELSE k.status END WHERE id=keep_id;
 UPDATE public.activities SET lead_id=keep_id,owner=COALESCE(k.owner,owner) WHERE lead_id=remove_id; UPDATE public.deals SET lead_id=keep_id,owner=k.owner WHERE lead_id=remove_id; UPDATE public.leads SET merged_into=keep_id WHERE id=remove_id; END $$;
REVOKE ALL ON FUNCTION public.crm_merge(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_merge(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.cms_access(scope text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (NOT EXISTS(SELECT 1 FROM public.crm_users WHERE user_id=auth.uid() AND (NOT active OR role='sales'))) AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.cms_members WHERE user_id=auth.uid() AND (role='owner' OR (scope='content' AND role='editor') OR (scope='leads' AND role='sales')))) $$;